           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#39;");
       }

       function validate(values) {
         const errors = {};
         const fullName = values.fullName.trim();
         const email = values.email.trim();
         const phone = values.phone.trim();

         if (!fullName) {
           errors.fullName = "Error: Enter your full name.";
         }

         if (!email) {
           errors.email = "Error: Enter your email address.";
         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
           errors.email = "Error: Enter a valid email address.";
         }

         if (phone && !/^[+()\-\s0-9]{7,}$/.test(phone)) {
           errors.phone = "Error: Enter a phone number using digits and standard separators.";
         }

         return errors;
       }

       function fieldErrorId(field) {
         return field.id + "-error";
       }

       function fieldHelpId(field) {
         return field.id + "-help";
       }

       function Field(field) {
         const value = state.values[field.name];
         const error = state.errors[field.name];
         const hasError = state.submitted && Boolean(error);
         const describedBy = [fieldHelpId(field), hasError ? fieldErrorId(field) : ""].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${field.id}">
               ${escapeHTML(field.label)}
               ${field.required ? '<span class="required" aria-hidden="true"> *</span>' : ''}
             </label>
             <input
               id="${field.id}"
               name="${field.name}"
               type="${field.type}"
               value="${escapeHTML(value)}"
               ${field.autocomplete ? `autocomplete="${field.autocomplete}"` : ""}
               ${field.required ? "required" : ""}
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
               ${hasError ? 'aria-invalid="true"' : ""}
               placeholder="${escapeHTML(field.placeholder)}"
             />
             <p id="${fieldHelpId(field)}" class="help-text">${escapeHTML(field.helpText)}</p>
             <p id="${fieldErrorId(field)}" class="error-text" ${hasError ? "" : "hidden"}>${escapeHTML(error || "")}</p>
           </div>
         `;
       }

       function App() {
         return `
           <section class="hero" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">Contact our support team</h1>
             <p class="lede">Send us your details and we’ll get back to you by email.</p>
           </section>

           <section class="card" aria-labelledby="form-title">
             <h2 id="form-title" class="sr-only" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden;">Support contact form</h2>
             <form id="support-form" novalidate>
               ${fields.map(Field).join("")}
               <div class="actions">
                 <button type="submit">Send message</button>
               </div>
             </form>
           </section>
         `;
       }

       function render() {
         app.innerHTML = App();

         const form = document.getElementById("support-form");
         fields.forEach((field) => {
           const input = document.getElementById(field.id);
           input.value = state.values[field.name];
           input.addEventListener("input", (event) => {
             state.values[field.name] = event.target.value;
             if (state.submitted) {
               state.errors = validate(state.values);
               render();
               document.getElementById(field.id).focus();
             }
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;
           state.errors = validate(state.values);

           if (Object.keys(state.errors).length > 0) {
             render();
             const firstInvalid = fields.find((field) => state.errors[field.name]);
             document.getElementById(firstInvalid.id).focus();
             return;
           }

           form.innerHTML = `
             <div class="form-field" aria-live="polite">
               <p class="help-text" style="margin:0;">Thanks — your message is ready to send.</p>
             </div>
           `;
         });
       }

       render();
     </script>
